package com.mockarena.evaluation.security;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.MediaType; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.Map;
public final class EvaluationWorkloadTokenFilter extends OncePerRequestFilter { private final byte[] expected; private final ObjectMapper json; public EvaluationWorkloadTokenFilter(String token,ObjectMapper json){expected=token.getBytes(StandardCharsets.UTF_8);this.json=json;} @Override protected boolean shouldNotFilter(HttpServletRequest r){return !r.getRequestURI().startsWith("/internal/");} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String actual=r.getHeader("X-MockArena-Workload-Token");if(actual==null||!MessageDigest.isEqual(expected,actual.getBytes(StandardCharsets.UTF_8))){s.setStatus(401);s.setContentType(MediaType.APPLICATION_JSON_VALUE);json.writeValue(s.getOutputStream(),Map.of("code","UNAUTHENTICATED","message","Workload authentication is required"));return;}c.doFilter(r,s);} }
